`post_content_filtered` text NOT NULL ON CONFLICT REPLACE DEFAULT '' COLLATE NOCASE,
`post_parent` integer NOT NULL ON CONFLICT REPLACE DEFAULT '0',
`guid` text NOT NULL ON CONFLICT REPLACE DEFAULT '' COLLATE NOCASE,
